// Generate character hash from characterSpecs if available
// Only hash fields that affect character appearance in 2A/2B images
function generateCharacterHash(specs) {
  if (!specs) return null;
  const crypto = require('crypto');
  const characterHashSpec = {
    clothingStyle:  specs.clothingStyle || 't-shirt and shorts',
    favoriteColor:  specs.favoriteColor || 'blue',
    hairColor:      specs.hairColor || 'brown',
    hairStyle:      specs.hairStyle || 'short/straight',
    skinTone:       specs.skinTone || 'medium'
  };
  const hashString = JSON.stringify(characterHashSpec);
  return crypto.createHash('sha256').update(hashString).digest('hex').substring(0, 16);
}

