  character_specs: characterSpecs,
  character_hash: characterHash,
  customer_email: order.buyer?.email || null,
  customer_name: order.buyer?.name || null,
  shipping_address: order.orderDetails?.shippingAddress || null,
  product_info: order.orderDetails || null,
  purchase_date: order.purchaseDate || null,
  workflow_step: 'order_intake',
  status: 'new',
  marketplace_id: manifest.marketplaceId || null,
  book_specs: order.bookSpecs ?? null,
  display_order_id: order.displayOrderId ?? order.display_order_id ?? null,
  preview_hash: order.previewHash ?? order.preview_hash ?? null,
  shipping_tier: order.shippingTier ?? order.shipping_tier ?? null,
  thumbnail_url: order.thumbnailUrl ?? order.thumbnail_url ?? null
};

// Canonical group key for ALL orders (Amazon + D2C).
// - Amazon: root_order_id = Amazon root order id
// - D2C: root_order_id = checkout root UUID
body.root_order_id = manifest.siblingGroupId || manifest.amazonOrderId || body.orderId;

// Legacy mirror for Amazon only (leave null/undefined for D2C).
if (manifest.amazonOrderId) {
  body.amazon_order_id = manifest.siblingGroupId || manifest.amazonOrderId;
}

console.log('Upserting orderId:', body.orderId);
console.log('amazon_order_id:', body.amazon_order_id);

const headers = {
  'apikey': cfg.supabase.serviceKey,
  'Authorization': `Bearer ${cfg.supabase.serviceKey}`,
  'Prefer': 'return=representation',
  'Content-Type': 'application/json'
};

try {
  const patchRes = await this.helpers.request({
    method: 'PATCH',
    uri: `${cfg.supabase.url}/rest/v1/orders?orderId=eq.${encodeURIComponent(body.orderId)}`,
    headers: headers,
    body: JSON.stringify(body)
  });

  const patchParsed = typeof patchRes === 'string' ? JSON.parse(patchRes) : patchRes;
  const patchData = Array.isArray(patchParsed) ? patchParsed[0] : patchParsed;
  if (patchData && typeof patchData === 'object' && Object.keys(patchData).length > 0) {
    console.log('✅ Supabase PATCH successful (record updated)');
    return [{ json: { ...input, ...patchData, orderId: body.orderId, manifest, r2Key } }];
  }

  console.log('Record not found, trying POST insert...');
  try {
    const postRes = await this.helpers.request({
      method: 'POST',
      uri: `${cfg.supabase.url}/rest/v1/orders`,
      headers: headers,
      body: JSON.stringify(body)
    });

    const postParsed = typeof postRes === 'string' ? JSON.parse(postRes) : postRes;
    const postData = Array.isArray(postParsed) ? postParsed[0] : postParsed;

    console.log('✅ Supabase POST successful (record inserted)');

    if (!postData || typeof postData !== 'object') {
      throw new Error('Invalid response from Supabase POST: ' + JSON.stringify(postRes));
    }

    return [{ json: { ...input, ...postData, orderId: body.orderId, manifest, r2Key } }];
  } catch (postError) {
    const errorMsg = postError.response 
      ? `POST failed (${postError.response.status}): ${JSON.stringify(postError.response.data)}`
      : `POST failed: ${postError.message}`;
    throw new Error(errorMsg);
  }

} catch (error) {
  if (error.response) {
    throw new Error(`Supabase error (${error.response.status}): ${JSON.stringify(error.response.data)}`);
  }
  throw error;
}

// Build 1‑manifest.json with normalized fields
const j = $input.first().json;
const r2Key = `book-mvp-simple-adventure/orders/${j.orderId}/manifests/1-manifest.json`;

// Read from top-level (Normalize Payload promotes these)
const marketplaceId = j.marketplaceId ?? j._raw?.marketplaceId ?? null;
const amazonOrderId = j.amazonOrderId ?? j._raw?.amazonOrderId ?? null;
const rootOrderId = j.rootOrderId ?? j.orderId;
const isSiblingOrder = j.isSiblingOrder ?? false;

// Determine if this is an Amazon order
const isAmazonOrder = !!(marketplaceId || amazonOrderId);
const resolvedAmazonOrderId = isAmazonOrder ? (amazonOrderId || j.orderId) : null;

// siblingGroupId = root group ID for sibling/group queries (all members share this value)
const siblingGroupId = (isSiblingOrder || isAmazonOrder) ? rootOrderId : null;

const manifest = {
  schema: "lhb.run-manifest@v2.1",
  runStamp: new Date().toISOString(),
  orderId: j.orderId,  // Per-book identifier (synthetic for siblings)
  ...(resolvedAmazonOrderId ? { amazonOrderId: resolvedAmazonOrderId } : {}),
  ...(siblingGroupId ? { siblingGroupId } : {}),
  ...(marketplaceId ? { marketplaceId } : {}),
  order: {
    purchaseDate: j.orderDate || j.purchaseDate || null,
    buyer: { email: j.customerEmail, ...j.buyer },
    dedication: j.dedication,
    characterSpecs: j.characterSpecs,
    bookSpecs: j.bookSpecs,
    ...(j.displayOrderId != null || j.display_order_id != null ? { displayOrderId: j.displayOrderId ?? j.display_order_id } : {}),
    ...(j.previewHash != null || j.preview_hash != null ? { previewHash: j.previewHash ?? j.preview_hash } : {}),
    ...(j.shippingTier != null || j.shipping_tier != null ? { shippingTier: j.shippingTier ?? j.shipping_tier } : {}),
    ...(j.thumbnailUrl != null || j.thumbnail_url != null ? { thumbnailUrl: j.thumbnailUrl ?? j.thumbnail_url } : {}),
    orderDetails: {
      ...j.orderDetails,
      shippingAddress: {
        ...j.orderDetails.shippingAddress,
        phone: j.orderDetails.shippingAddress?.phone
      }
    }
  }
};

return [{ json: { manifest, r2Key, orderId: j.orderId } }];
